def path(g):return '/games/'+g['slug']+'/'
def is_file(g):return g.get('status')=='files'
def launch_url(g):return path(g) if is_file(g) else g['url']
def launch_label(g):
    return 'How to play' if is_file(g) else 'Unavailable · details' if g.get('status')=='offline' else 'Check game website' if g.get('status')=='unverified' else 'Visit game website' if g.get('status') not in ('browser','instant','demo') else 'Play on provider site' 
def card(g):
    """Primary game interactions open the provider directly."""
    url=escape(launch_url(g), quote=True)
    title=escape(g['title'])
    cover=(f'<img class="game-cover" src="{escape(g["cover"], quote=True)}" alt="{title} gameplay image" loading="lazy" decoding="async" width="640" height="360">' if g.get('cover') else '<span class="art-grid"></span><span class="art-shape"></span>')
    play_label=escape(launch_label(g))
    target = '' if g.get("status")=="files" else ' target="_blank" rel="noopener noreferrer"'
    return f'''<article class="game-card" data-category="{g['cat']}" data-categories="{escape(' '.join(g['categories']))}" data-title="{escape(g['title'].lower())}" data-tags="{escape(' '.join(g['tags']).lower())}"><a href="{url}"{target} class="card-art art-{g['art']}" aria-label="{play_label} {title}">{cover}<span class="card-play">↗</span><span class="art-label">{title}</span></a><div class="card-info"><div><h3><a href="{url}"{target}>{title}</a></h3><p>{escape(g['tags'][0])} <span>·</span> {escape(g['type'])}</p></div><button class="save-btn" aria-label="Save {title}" data-save="{g['slug']}" title="Save game">♡</button></div><a class="card-launch" href="{url}"{target} aria-label="{play_label} {title}">{play_label} <span aria-hidden="true">↗</span></a></article>'''

